    checkReqStatus: function (statusCode) {
        var changeBtn = this.lookupReference("btnChangeRequester"),
            userCombo = this.lookupReference("onBehalfCombo");
        if (statusCode === 1 || statusCode === 12) {
            changeBtn.show();
        } else {
            changeBtn.hide();
            //don't want to have both the combo and the hidden field for requesterId
            if (userCombo) {
                userCombo.destroy();
            }
        }
    },

    loadForm: function (rec) {
        var refs = this.getReferences(),
            radioGrp = refs.requesterRg,
            onBehalfCombo = refs.onBehalfCombo,
            comboType = refs.comboType,
            form = refs.form;
        if (rec.data.creatorId !== rec.data.requesterId) {
            radioGrp.setValue({
                whoVal: "notme"
            });
        } else {
            radioGrp.setValue({
                whoVal: "self"
            });
        }
        form.loadRecord(rec);
        //for strange reason, the loadrecord above doesn't set value in this combo
        //so do it manually here
        if (onBehalfCombo) {
            onBehalfCombo.setValue(rec.data.requesterId);
        }
        comboType.setValue(rec.data.purchaseTypeId);
    },

