    onHomeAddrDeliveryOptChange: function (field, newValue, oldValue, eOpts) {
        var refs = this.getReferences(),
            title = "";
        //due to PII concern, if deliver to home, home address cannot be stored in the
        //system. Instead, once the request is at BCH, an email will be sent to the
        //requester to ask for where to deliver to
        if (newValue && newValue === true) {
            //title='Delivery Address (For Home Address: Full Address)';
            //refs.rgDelAddr.hide();
            refs.fsDelivAddr.hide();
            refs.taDelivAddr.disable();
            refs.dfHomeAddr.show();
        } else {
            title = "Delivery Address (For NIST Site: Location, Bldg and Office#. For Non NIST site: Full Address)";
            //refs.rgDelAddr.show();
            refs.fsDelivAddr.show();
            refs.taDelivAddr.enable();
            refs.dfHomeAddr.hide();
        }

        refs.fsDelivAddr.setTitle(title);
    },

    onDelAddrChange: function (field, newValue, oldValue, eOpts) {
        var model = this.getViewModel(),
            user = model.get("loggedInUser"),
            addr = this.lookupReference("taDelivAddr");
        if (newValue && newValue.addr === "grsd") {
            addr.setValue(
                "Attn: GRSD\n" + "NIST\n" + "Bldg 245/H113\n" + "100 Bureau Drive\n" + "Gaithersburg, MD 20899"
            );
        } else if (newValue && newValue.addr === "ncnr") {
            var reqRg = this.lookupReference("requesterRg").getValue().whoVal,
                name = "";
            if (reqRg === "self") {
                name = user.lastName + ", " + user.firstName;
            } else {
                var comboName = this.lookupReference("onBehalfCombo"),
                    rec = comboName.getSelectedRecord();
                if (rec) {
                    name = rec.get("fullName");
                }
            }
            addr.setValue(
                name +
                    "\n" +
                    "c/o NCNR Health Physics\n" +
                    "NIST\n" +
                    "Bldg 235/A134\n" +
                    "100 Bureau Drive\n" +
                    "Gaithersburg, MD 20899"
            );
        }
    },

    onPurchaseTypeAfterRender: function (field, eOpts) {
        // get the info icon element
        var infoIconEl = Ext.get("giPurchaseTypeInfoBtn");

        // add click listener to the info icon
        if (infoIconEl) {
            infoIconEl.on("click", function () {
                Ext.Ajax.request({
                    url: "resources/htmls/purchaseTypeDefinition.html", // Path to your HTML file
                    method: "GET",
                    success: function (response) {
                        var htmlContent = response.responseText;
                        // Create and open a new window with the HTML content
                        var popupWindow = window.open(
                            "",
                            "PurchaseTypeDefinition",
                            "width=600,height=250,resizable=yes,scrollbars=yes"
                        );
                        //Wait for the window to fully load before setting the content.
                        setTimeout(function() {
                            popupWindow.document.body.innerHTML = htmlContent;
                        }, 600);
                        //the write function is deprecated
                        //popupWindow.document.write(htmlContent);
                        //popupWindow.document.close();
                    },
                    failure: function (response) {
                        bcp.util.CommonUtil.showError("Failed to load Purchase Type Definition.");
                    }
                });
            });
        }
    },

