    onEditMcDataClick: function (button, e, eOpts) {
        var me = this,
            model = this.getViewModel(),
            refs = this.getReferences(),
            form = refs.form,
            record = me.getViewModel().get("record"),
            reqId = record.get("requestId"),
            store = this.getStore("mcCategories");

        var editmcwindow = Ext.create("widget.editmissioncriticalwindow", {
            reference: "editmcwindow",
            store: store
        });
        //set event listeners
        editmcwindow.on({
            cancel: {
                fn: function (data) {
                    editmcwindow.destroy();
                },
                scope: this,
                single: true
            }
        });

        editmcwindow.on({
            save: {
                fn: function (data) {
                    //set value
                    record.set("missionCriticalCategoryId", data.missionCriticalCategoryId);
                    record.set("missionCriticalJustification", data.missionCriticalJustification);

                    //update request record
                    Ext.Ajax.request({
                        url: bcp.config.Runtime.getServerBaseUrl() + "requests/" + reqId,
                        method: "PUT",
                        scope: this,
                        jsonData: Ext.encode(record.data),
                        success: function (response) {
                            bcp.util.CommonUtil.ajaxSuccessHandler(response, function (result) {
                                record = Ext.create("bcp.model.BcpRequest", result.data);
                                model.set("record", record);
                                form.loadRecord(record);

                                editmcwindow.destroy();
                            });
                        }
                    });
                },
                scope: this,
                single: true
            }
        });

        var mcCategoryCombo = editmcwindow.down("#mcCategoryCombo");
        var mcJustificationTextArea = editmcwindow.down("#mcJustificationTextArea");

        mcCategoryCombo.setValue(record.get("missionCriticalCategoryId"));
        mcJustificationTextArea.setValue(record.get("missionCriticalJustification"));

        //add to the parent view
        this.view.add(editmcwindow);

        // Show the window
        editmcwindow.show();
    },

    //BANK-560
    //fix a UI confusion when a user select a RAM address option, then decide to remove it, there's no reset
    //button and the user can only remove the text manually and the selected option is still there
    //adding this reset button will reset both the textarea and the radio optionss
    onResetAddr: function (button, e, eOpts) {
        var addr = this.lookupReference("taDelivAddr"),
            rgDelAddr = this.lookupReference("rgDelAddr");
        rgDelAddr.reset();
        addr.reset();
    },

    onViewAdded: function (component, container, pos, eOpts) {
        var model = this.getViewModel(),
            user = model.get("loggedInUser"),
            userId = user.peopleId,
            form = this.getView().getForm(),
            refs = this.getReferences(),
            layout = this.view.getLayout(),
            today = new Date(),
            record = model.get("record"),
            newRecord = {},
            currentStatus = 0,
            isDynamic = 0,
            routeId = "";

        //limit the date range for needed by date
        refs.neededByDf.minValue = today;

        /*tomorrow = new Date(today),
        theDateAfterTomorrow=new Date(today);

        tomorrow.setDate(today.getDate()+1);
        theDateAfterTomorrow.setDate(today.getDate()+2);
        */

        //check request status
        if (record) {
            currentStatus = record.get("statusCode");
            //check if it's a dynamic route such as ITSO or AA, which might carry the same status as fixed route
            isDynamic = record.get("isDynamic");
        }
        //check which main view this component is in
        var routeOwner = this.getView().up("[routeId]");
        routeId = routeOwner ? routeOwner.routeId : "";

        //if view is read only, show readonly view
        if (component.readOnly) {
            layout.setActiveItem(1);
            //issue 618, give reviewer, DC and DR the ability to update mission critical category and justification
            //when they review requests in their pending action
            if (
                routeId == "pendingrequests" &&
                isDynamic == 0 &&
                (currentStatus == 5 || currentStatus == 17 || currentStatus == 18)
            ) {
                refs.btnEditMcData.show();
            } else {
                refs.btnEditMcData.hide();
            }
        } else {
            //if view is editable, show form view
            layout.setActiveItem(0);
            if (user.staffType === "NIST Associate") {
                newRecord = Ext.create("bcp.model.BcpRequest", {
                    requestId: 0,
                    creatorId: userId,
                    requestedForId: userId,
                    requesterId: user.bossId
                });
                refs.requesterIdHf.disable();
                refs.notmeRb.setBoxLabel("NIST Federal Employee");
            } else {
                newRecord = Ext.create("bcp.model.BcpRequest", {
                    requestId: 0,
                    creatorId: userId,
                    requestedForId: -1,
                    requesterId: userId
                });
            }
            model.set("record", newRecord);

            // Clear form
            form.reset();
            // Set record
            form.loadRecord(newRecord);

            //if associates try to do it for someone else, that someone must be a fed
            if (user.staffType === "NIST Associate") {
                refs.requesterRg.setValue({
                    whoVal: "notme"
                });
                refs.selfRb.hide();
                refs.selfRb.disable();
                refs.onBehalfCombo.setValue(newRecord.get("requesterId"));
            } else {
                refs.selfRb.show();
                refs.selfRb.enable();
                refs.requesterRg.setValue({
                    whoVal: "self"
                });
            }

            //even if the form is editable (administrative staff need edit after submission), 
            // unless the request is not submitted yet, cannot allow editing MCC and MCJ 
            if(![0,1,12].includes(currentStatus)){
                refs.comboMcCategory.setReadOnly(true);
                refs.mcJustification.setReadOnly(true);
            }
        }
    }
